import { screen, within } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../tests/utils";
import {
  ConversationEventType,
  type ConversationEvent,
  type Skill,
  type SkillCatalog,
  type SkillState,
} from "../types";
import { MemorySection } from "./MemorySection";
import { SkillMemoryDetails } from "./SkillMemoryDetails";

const travelNotice: Skill = {
  id: "travel_notice",
  name: "Travel Notice",
  description: null,
  is_default: false,
  engine_managed: false,
  disabled: false,
  sections: [],
  blocks: {},
  referenced_skills: [],
  tool_names: [],
  hidden: false,
};

const skillCatalogWithSkill: SkillCatalog = { travel_notice: travelNotice };

const skillState: SkillState = {
  active_skill: { skill_id: "travel_notice", ordered_block_id: "travel_notice", step_id: null },
  blocks: {},
  evaluated_conditions: {},
  tools: {},
  llm_calls: [],
  memory: {
    "travel_notice.destination": {
      value: "Atlantis",
      source: "llm",
      scope: "skill",
      description: "Where the customer is travelling.",
    },
    "travel_notice.notice_submitted": {
      value: null,
      source: null,
      scope: "skill",
      description: null,
    },
    "project.selected_card_id": {
      value: "c1",
      source: "tool",
      scope: "project",
      description: null,
    },
    "system.correction_resume_point": {
      value: { frame_id: "f1", step_id: "s1" },
      source: "system",
      scope: "system",
      description: null,
    },
    "system.__discovered__": {
      value: [
        {
          key: "travels_with_partner",
          value: true,
          description: "Mentioned travelling with a partner.",
          turn_idx: 3,
          confidence: 0.9,
          captured_by_skill: "travel_notice",
        },
      ],
      source: "system",
      scope: "system",
      description: null,
    },
  },
};

function memoryWrite(name: string, value: unknown): ConversationEvent {
  return {
    __typename: "ConversationEvent",
    id: `write-${name}`,
    conversationEventType: ConversationEventType.MemorySet,
    name,
    slotValue: value,
    timestamp: "2026-01-01T00:00:00.000Z",
    originalTimestamp: 0,
    metadata: { parseData: {} },
  };
}

describe("SkillMemoryDetails", () => {
  it("titles a skill section from the catalog display name", () => {
    renderWithProviders(<SkillMemoryDetails />, {
      initialStoreState: { skillCatalog: skillCatalogWithSkill, skillState },
    });
    const section = screen.getByTestId("Travel Notice-section");
    expect(within(section).getByRole("heading")).toHaveTextContent("Travel Notice");
    expect(section).toHaveTextContent("destination");
  });

  it("falls back to the humanized skill id without a catalog entry", () => {
    renderWithProviders(<SkillMemoryDetails />, { initialStoreState: { skillState } });
    expect(screen.getByTestId("Travel notice-section")).toHaveTextContent("destination");
  });

  it("groups memory into per-skill, project and system sections with badges", () => {
    renderWithProviders(<SkillMemoryDetails />, { initialStoreState: { skillState } });
    expect(screen.getByTestId("Travel notice-section")).toHaveTextContent("destination");
    expect(screen.getByTestId("Project-section")).toHaveTextContent("selected_card_id");
    expect(screen.getByTestId("System-section")).toHaveTextContent("correction_resume_point");
    // One badge on the destination entry, one on the scratchpad fact.
    const sources = screen.getAllByTestId("memory-source");
    expect(sources.filter((el) => el.getAttribute("data-source") === "llm")).toHaveLength(2);
    expect(sources.filter((el) => el.getAttribute("data-source") === "tool")).toHaveLength(1);
    expect(screen.getAllByTestId("memory-entry").length).toBeGreaterThan(0);
  });

  it("renders the engine provenance badge on system-set entries", () => {
    renderWithProviders(<SkillMemoryDetails />, { initialStoreState: { skillState } });
    const row = screen.getByTestId("slot-system.correction_resume_point");
    expect(within(row).getByTestId("memory-source")).toHaveAttribute("data-source", "system");
  });

  it("keeps a written-then-cleared entry visible with a dash and no badge", () => {
    renderWithProviders(<SkillMemoryDetails />, {
      initialStoreState: {
        skillState,
        // notice_submitted was cleared before destination was written, so its
        // dash row survives the filter and ranks below the newer write.
        slotRelatedEvents: [
          memoryWrite("travel_notice.notice_submitted", null),
          memoryWrite("travel_notice.destination", "Atlantis"),
        ],
      },
    });
    const row = screen.getByTestId("slot-travel_notice.notice_submitted");
    expect(row).toHaveTextContent("–");
    expect(row.querySelector("[data-testid='memory-source']")).toBeNull();
    const section = screen.getByTestId("Travel notice-section");
    const rows = within(section).getAllByTestId(/^slot-travel_notice\./);
    expect(rows.at(-1)).toBe(row);
  });

  it("hides an entry that was never set", () => {
    renderWithProviders(<SkillMemoryDetails />, { initialStoreState: { skillState } });
    // notice_submitted is null with no witnessed write in this render.
    expect(screen.queryByTestId("slot-travel_notice.notice_submitted")).toBeNull();
    expect(screen.getByTestId("slot-travel_notice.destination")).toBeInTheDocument();
  });

  it("renders discovered facts as a separate Discovered section", () => {
    renderWithProviders(<SkillMemoryDetails />, { initialStoreState: { skillState } });
    const discovered = screen.getByTestId("Discovered-section");
    expect(discovered).toHaveTextContent("travels_with_partner");
    expect(discovered).toHaveTextContent("true");
    // The raw sidecar slot itself is not listed in the system section.
    expect(screen.queryByTestId("slot-system.__discovered__")).toBeNull();
  });

  it("orders the discovered section between the skill and shared sections by default", () => {
    renderWithProviders(<SkillMemoryDetails />, { initialStoreState: { skillState } });
    const skillSection = screen.getByTestId("Travel notice-section");
    const discovered = screen.getByTestId("Discovered-section");
    const projectSection = screen.getByTestId("Project-section");
    expect(
      skillSection.compareDocumentPosition(discovered) & Node.DOCUMENT_POSITION_FOLLOWING,
    ).toBeTruthy();
    expect(
      discovered.compareDocumentPosition(projectSection) & Node.DOCUMENT_POSITION_FOLLOWING,
    ).toBeTruthy();
  });

  it("moves the most recently written section to the top", () => {
    renderWithProviders(<SkillMemoryDetails />, {
      initialStoreState: {
        skillState,
        slotRelatedEvents: [
          memoryWrite("travel_notice.destination", "Atlantis"),
          memoryWrite("project.selected_card_id", "c1"),
        ],
      },
    });
    const projectSection = screen.getByTestId("Project-section");
    const skillSection = screen.getByTestId("Travel notice-section");
    expect(
      projectSection.compareDocumentPosition(skillSection) & Node.DOCUMENT_POSITION_FOLLOWING,
    ).toBeTruthy();
  });
});

describe("MemorySection mode fork", () => {
  it("renders the skill memory view in skill mode", () => {
    renderWithProviders(<MemorySection />, {
      initialStoreState: {
        engineType: "mantle",
        skillCatalog: skillCatalogWithSkill,
        skillState,
      },
    });
    expect(screen.getByTestId("Travel Notice-section")).toBeInTheDocument();
  });

  it("shows the placeholder in skill mode when the memory map is empty", () => {
    renderWithProviders(<MemorySection />, {
      initialStoreState: {
        engineType: "mantle",
        skillCatalog: {},
        skillState: { ...skillState, memory: {} },
      },
    });
    expect(screen.getByText("Memory will be shown here.")).toBeInTheDocument();
    expect(screen.queryByTestId("Travel Notice-section")).toBeNull();
  });

  it("shows the placeholder when every entry was never set", () => {
    // Reviewer feedback: rows that were never written must not render. With the
    // whole map never-set the derived view is empty, so the pane falls back to
    // the NoData placeholder rather than a wall of dashes.
    const allNeverSetState: SkillState = {
      ...skillState,
      memory: {
        "travel_notice.destination": {
          value: null,
          source: null,
          scope: "skill",
          description: null,
        },
        "project.selected_card_id": {
          value: null,
          source: null,
          scope: "project",
          description: null,
        },
      },
    };
    renderWithProviders(<MemorySection />, {
      initialStoreState: {
        engineType: "mantle",
        skillCatalog: skillCatalogWithSkill,
        skillState: allNeverSetState,
      },
    });
    expect(screen.getByText("Memory will be shown here.")).toBeInTheDocument();
    expect(screen.queryByTestId("Travel Notice-section")).toBeNull();
  });

  it("shows the pane with a dash row when an entry was written then cleared", () => {
    // A witnessed write keeps the (now-null) row visible, so the derived view is
    // non-empty and the pane renders instead of the placeholder.
    const clearedState: SkillState = {
      ...skillState,
      memory: {
        "travel_notice.destination": {
          value: null,
          source: null,
          scope: "skill",
          description: null,
        },
      },
    };
    renderWithProviders(<MemorySection />, {
      initialStoreState: {
        engineType: "mantle",
        skillCatalog: skillCatalogWithSkill,
        skillState: clearedState,
        slotRelatedEvents: [memoryWrite("travel_notice.destination", null)],
      },
    });
    expect(screen.queryByText("Memory will be shown here.")).toBeNull();
    const row = screen.getByTestId("slot-travel_notice.destination");
    expect(within(row).getByTestId("slot-value")).toHaveTextContent("–");
  });

  it("keeps the slot view for flow-based projects", () => {
    renderWithProviders(<MemorySection />, {
      initialStoreState: {
        slots: { amount: 42 },
        engineType: "calm",
        skillCatalog: null,
        skillState: null,
      },
    });
    expect(screen.queryByTestId("Travel Notice-section")).toBeNull();
    expect(screen.queryByTestId("Travel notice-section")).toBeNull();
  });
});
